local OTHUB_IMAGE = {}
OTHUB_IMAGE.image = function(entry)
    if type(entry) ~= "table" or type(entry.file) ~= "string" then return nil end
    local path = entry.file
    local ok, asset = pcall(function()
        if not (isfile and isfile(path)) then
            local dir = path:match("^(.*)/")
            if dir and isfolder and not isfolder(dir) and makefolder then makefolder(dir) end
            local b64 = entry.png
            if type(b64) ~= "string" or b64 == "" then return nil end
            local dec = (crypt and crypt.base64decode) or (crypt and crypt.base64 and crypt.base64.decode)
                or base64_decode or (base64 and base64.decode)
            if not dec then return nil end
            writefile(path, dec(b64))
        end
        return getcustomasset(path)
    end)
    return ok and asset or nil
end

