-- Cosmetics + Name Changer: rebuilt against the game's own appearance system,
-- because those modules were never fetched during the original capture.
pcall(function()
    local prev = getgenv().OTHUB_COSMETICS
    if type(prev) == "table" and type(prev.destroy) == "function" then prev.destroy() end
end)
local OTHUB_COSMETICS = (function()
-- OT HUB :: Cosmetics, Name Changer (rebuilt)
-- The original modules were never fetched during the capture. These are rebuilt
-- from the original menu tooltips (the spec) on top of Practical Basketball's own
-- client systems. Everything is local: only your screen changes.
--
--   Config.Accessories / Config.GreenEffects        item catalogues
--   Controllers.Characters:GetFromString().Appearance   appearanceData + LoadAppearance
--   Services.InventoryService.EquipItem / EquipEffect   locker Equip buttons
--   Controllers.Visuals.objects.GreenEffects.RunEffect  green trail + rim effect
--   ReplicatedStorage.Assets.Models.HeadLogo            overhead staff logo

local RS = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LP = Players.LocalPlayer
local g = (typeof(getgenv) == "function" and getgenv()) or _G

local M = { enabled = false, pending = {}, alive = true }

local accCfg, fxCfg = {}, {}
pcall(function() accCfg = require(RS.Aero.Shared.Config.Accessories) end)
pcall(function() fxCfg = require(RS.Aero.Shared.Config.GreenEffects) end)

-- ------------------------------------------------------------------ game handles
local Controllers, Services
local function findAero()
    if (Controllers and Services) or not getgc then return end
    for _, o in ipairs(getgc(true)) do
        if type(o) == "table" then
            if not Controllers and type(rawget(o, "Characters")) == "table"
                and type(rawget(o, "Visuals")) == "table" and rawget(o, "Player") ~= nil then
                Controllers = o
            elseif not Services and type(rawget(o, "InventoryService")) == "table"
                and rawget(o, "InterfaceService") ~= nil then
                Services = o
            end
            if Controllers and Services then break end
        end
    end
end

-- our Appearance object (has .model, .appearanceData, :LoadAppearance)
local function appearance()
    findAero()
    if Controllers then
        local ok, obj = pcall(function() return Controllers.Characters:GetFromString(LP.Name) end)
        if ok and type(obj) == "table" then
            local ap = obj.Appearance
            if type(ap) == "table" and type(ap.appearanceData) == "table" then
                local m = ap.model
                if typeof(m) == "Instance" and m.Parent then return ap end
            end
        end
    end
    return nil
end
M.controller = appearance

local function profile()
    findAero()
    local p = Controllers and Controllers.Player
    return p and p.ProfileData or nil
end

local function copy(v)
    if type(v) ~= "table" then return v end
    local t = {}
    for k, x in pairs(v) do t[k] = copy(x) end
    return t
end

-- ------------------------------------------------------------------ pickers
-- menu flag -> { appearanceData key, kind }
M.MAP = {
    oh_cos_hat        = { "Hats",           "array"  },
    oh_cos_hair       = { "Hair",           "array"  },
    oh_cos_glasses    = { "Glasses",        "array"  },
    oh_cos_facialhair = { "FacialHair",     "array"  },
    oh_cos_chain      = { "Chain",          "array"  },
    oh_cos_backpack   = { "Backpack",       "array"  },
    oh_cos_shirt      = { "Shirt",          "string" },
    oh_cos_pants      = { "Pants",          "string" },
    oh_cos_jersey     = { "Jersey",         "string" },
    oh_cos_sleeve     = { "Compression",    "string" },
    oh_cos_legsleeve  = { "LegCompression", "string" },
    oh_cos_mascot     = { "Mascot",         "mascot" },
    oh_cos_shoes      = { "Shoes",          "shoes"  },
    oh_cos_skin       = { "SkinTone",       "skin"   },
}
local ARRAY_KEYS = { Hats = true, Hair = true, Glasses = true, FacialHair = true, Chain = true, Backpack = true }
local STRING_KEYS = { Shirt = true, Pants = true, Jersey = true, Compression = true, LegCompression = true }

local LOGOS = { "Owner", "YouTube", "Twitch", "TikTok", "Moderator", "Music", "OT HUB" }
local EMOJI = {
    "\u{1F525}", "\u{1F451}", "\u{1F480}", "\u{1F410}", "\u{2B50}", "\u{1F48E}",
    "\u{26A1}", "\u{1F3C0}", "\u{1F608}", "\u{1F3AF}", "\u{1F4B0}", "\u{2764}\u{FE0F}",
}
local LOGO_CHILD = { TikTok = "Tiktok" }
local LOGO_COLORS = {
    White = Color3.fromRGB(255, 255, 255), Gold = Color3.fromRGB(255, 200, 40),
    Red = Color3.fromRGB(255, 60, 60), Purple = Color3.fromRGB(170, 90, 255),
    Green = Color3.fromRGB(60, 220, 110), Blue = Color3.fromRGB(70, 150, 255),
    Pink = Color3.fromRGB(255, 110, 190),
}

local function noneFirst(list)
    table.sort(list, function(a, b)
        if a == "None" then return b ~= "None" end
        if b == "None" then return false end
        return a:lower() < b:lower()
    end)
    return list
end

-- option list for a flag this module fills in (nil = not ours)
function M.options(flag)
    if flag == "oh_cos_greenfx" then
        local list = { "None" }
        for k in pairs(type(fxCfg.Effects) == "table" and fxCfg.Effects or {}) do
            if k ~= "None" then list[#list + 1] = k end
        end
        return noneFirst(list)
    elseif flag == "oh_cos_logo" then
        local list = { "None" }
        for _, n in ipairs(LOGOS) do list[#list + 1] = n end
        for _, e in ipairs(EMOJI) do list[#list + 1] = e end
        return list
    end
    local m = M.MAP[flag]
    if not m then return nil end
    local list = { "None" }
    if m[2] == "mascot" then
        local folder = RS:FindFirstChild("Accessories") and RS.Accessories:FindFirstChild("Mascots")
        for _, c in ipairs(folder and folder:GetChildren() or {}) do list[#list + 1] = c.Name end
    else
        for k in pairs(type(accCfg[m[1]]) == "table" and accCfg[m[1]] or {}) do
            if type(k) == "string" and k ~= "None" then list[#list + 1] = k end
        end
    end
    return noneFirst(list)
end

-- the look you really have, captured before the first override
local baseline, baselineModel
local function snapshot(ap)
    if baseline and baselineModel == ap.model then return end
    baseline, baselineModel = copy(ap.appearanceData), ap.model
end

-- The server's copy of what you really have equipped. Preferred over the local
-- snapshot, which can carry leftovers from an earlier run.
local function truth()
    findAero()
    local p = Controllers and Controllers.Player
    local sd = p and p.SlotData
    local a = sd and sd.Appearance
    return type(a) == "table" and a or nil
end

local function restoreKey(ad, key)
    local t = truth()
    if t and t[key] ~= nil then
        ad[key] = copy(t[key])
    elseif not t and baseline and baseline[key] ~= nil then
        ad[key] = copy(baseline[key])
    else
        ad[key] = nil
    end
end

local function isNone(v) return v == nil or v == "None" or v == "" end

local function writeField(ad, flag, value)
    local m = M.MAP[flag]
    if not m then return false, "unknown flag" end
    local key, kind = m[1], m[2]
    if isNone(value) then
        restoreKey(ad, key)             -- None = the one you really have
        return true
    end
    if kind == "array" then
        local colour = { 255, 255, 255 }
        local prev = ad[key]
        if type(prev) == "table" and type(prev[1]) == "table" then
            colour = copy(prev[1][2] or prev[1].Color or colour)
        end
        ad[key] = { { value, colour } }
    elseif kind == "string" then
        ad[key] = value
    elseif kind == "mascot" then
        ad.Mascot = value
    elseif kind == "shoes" then
        local colour = { 255, 255, 255 }
        ad.Shoes = { RightShoe = { value, colour }, LeftShoe = { value, copy(colour) } }
    elseif kind == "skin" then
        local col = type(accCfg.SkinTone) == "table" and accCfg.SkinTone[value]
        if typeof(col) == "Color3" then
            ad.SkinTone = { math.floor(col.R * 255 + 0.5), math.floor(col.G * 255 + 0.5), math.floor(col.B * 255 + 0.5) }
        elseif type(col) == "table" then
            ad.SkinTone = { col[1], col[2], col[3] }
        else
            return false, "unknown skin tone"
        end
    end
    return true
end

local function reload(ap)
    return pcall(function() ap:LoadAppearance() end)
end

local function applyAllPending(ap)
    local ad = ap.appearanceData
    for flag, value in pairs(M.pending) do
        if M.MAP[flag] then writeField(ad, flag, value) end
    end
end

local function applyPicker(flag, value)
    M.pending[flag] = value
    if not M.enabled then return true, "remembered (Cosmetics is off)" end
    local ap = appearance()
    if not ap then return true, "remembered (character not loaded yet)" end
    snapshot(ap)
    local ok, err = writeField(ap.appearanceData, flag, value)
    if not ok then return false, err end
    return reload(ap)
end

-- ------------------------------------------------------------------ green effect
local greenLocal            -- set by the locker's Effects tab while Unlock All is on
local function greenChoice()
    local pick = M.pending.oh_cos_greenfx
    if M.enabled and not isNone(pick) then return pick end
    return greenLocal
end

local greenHooked = false
local function hookGreen()
    if greenHooked then return end
    findAero()
    local obj = Controllers and Controllers.Visuals and Controllers.Visuals.objects
        and Controllers.Visuals.objects.GreenEffects
    if type(obj) ~= "table" or type(obj.RunEffect) ~= "function" then return end
    greenHooked = true
    g.__OTHUB_COS_ORIG = g.__OTHUB_COS_ORIG or {}
    local store = g.__OTHUB_COS_ORIG
    store.RunEffect = store.RunEffect or obj.RunEffect
    store.RunEffectOwner = obj
    local real = store.RunEffect
    obj.RunEffect = function(self, who, ball, goal, t, effect, ...)
        local mine = false
        if typeof(who) == "Instance" then mine = (who.Name == LP.Name)
        elseif type(who) == "string" then mine = (who == LP.Name) end
        if mine and M.alive then
            local pick = greenChoice()
            if pick and type(fxCfg.Effects) == "table" and fxCfg.Effects[pick] then effect = pick end
        end
        return real(self, who, ball, goal, t, effect, ...)
    end
end

-- ------------------------------------------------------------------ overhead logo
local logoGui, logoConn
local function clearLogo()
    if logoConn then logoConn:Disconnect() logoConn = nil end
    if logoGui then pcall(function() logoGui:Destroy() end) logoGui = nil end
end

local function applyLogo()
    clearLogo()
    local pick = M.pending.oh_cos_logo
    if not M.enabled or isNone(pick) then return true end
    local ap = appearance()
    local head = ap and ap.model and ap.model:FindFirstChild("Head")
    local template = RS:FindFirstChild("Assets") and RS.Assets:FindFirstChild("Models")
        and RS.Assets.Models:FindFirstChild("HeadLogo")
    if not head or not template then return false, "logo not available here" end

    local gui = template:Clone()
    gui.Name = "OTHUB_HeadLogo"
    for _, c in ipairs(gui:GetChildren()) do
        if c:IsA("GuiObject") then c.Visible = false end
    end
    local ref = gui:FindFirstChild("Owner")
    local shown, isEmoji
    local child = gui:FindFirstChild(LOGO_CHILD[pick] or pick)
    if child and child:IsA("ImageLabel") then
        shown = child
    elseif pick == "OT HUB" and ref then
        shown = ref:Clone()
        shown.Name = "OTHUB"
        local ok, asset = pcall(function()
            local f = "othub/ad-othub-logo-66d44604.png"
            if isfile and isfile(f) and getcustomasset then return getcustomasset(f) end
        end)
        if ok and asset then
            shown.Image = asset
            shown.ImageColor3 = Color3.new(1, 1, 1)
            shown.ScaleType = Enum.ScaleType.Fit
        else
            shown:Destroy()
            shown = nil
        end
        if shown then shown.Parent = gui end
    end
    if not shown then                       -- emoji, or OT HUB without its image
        local t = Instance.new("TextLabel")
        t.Name = "Glyph"
        t.BackgroundTransparency = 1
        t.TextScaled = true
        t.Font = Enum.Font.GothamBold
        t.TextColor3 = Color3.new(1, 1, 1)
        t.Text = (pick == "OT HUB") and "OT" or pick
        if ref then
            t.Size, t.Position, t.AnchorPoint = ref.Size, ref.Position, ref.AnchorPoint
        else
            t.Size = UDim2.fromScale(1, 1)
        end
        t.Parent = gui
        shown, isEmoji = t, (pick ~= "OT HUB")
    end
    shown.Visible = true

    local colour = M.pending.oh_cos_logo_color or "Default"
    if not isEmoji then                     -- emoji keep their own colours
        local function tint(c)
            if shown:IsA("ImageLabel") then shown.ImageColor3 = c else shown.TextColor3 = c end
        end
        if colour == "Rainbow" then
            logoConn = RunService.Heartbeat:Connect(function()
                tint(Color3.fromHSV((os.clock() * 0.25) % 1, 0.85, 1))
            end)
        elseif LOGO_COLORS[colour] then
            tint(LOGO_COLORS[colour])
        end
    end

    gui.Enabled = true
    gui.Parent = head
    logoGui = gui
    return true
end

-- ------------------------------------------------------------------ master toggle
function M.setEnabled(on)
    M.enabled = on and true or false
    local ap = appearance()
    -- No rig yet: keep the choice (the watcher applies it when the rig appears).
    -- Reporting failure here would make the menu bounce the toggle back off.
    if not ap then return true end
    snapshot(ap)
    local ad = ap.appearanceData
    if M.enabled then
        applyAllPending(ap)
    else
        for _, m in pairs(M.MAP) do restoreKey(ad, m[1]) end   -- your own look back
    end
    local ok, err = reload(ap)
    pcall(applyLogo)
    return ok, err
end

-- ------------------------------------------------------------------ unlock all
local UL = { on = false, added = {}, createdCat = {}, addedFx = {}, realGreen = nil, localItems = {} }

local function reallyOwned(cat, name)
    return not (UL.added[cat] and UL.added[cat][name])
end

local function localEquip(cat, name, side)
    local ap = appearance()
    if not ap then return nil end
    snapshot(ap)
    local ad = ap.appearanceData
    UL.localItems[cat] = UL.localItems[cat] or {}
    if cat == "Shoes" then
        local entry = { name, { 255, 255, 255 } }
        ad.Shoes = type(ad.Shoes) == "table" and ad.Shoes or {}
        if side == "Left" then ad.Shoes.LeftShoe = entry
        elseif side == "Right" then ad.Shoes.RightShoe = entry
        else ad.Shoes.RightShoe, ad.Shoes.LeftShoe = entry, copy(entry) end
        UL.localItems[cat][name] = true
    elseif ARRAY_KEYS[cat] then
        local list = type(ad[cat]) == "table" and ad[cat] or {}
        local at
        for i, v in ipairs(list) do
            if type(v) == "table" and (v[1] == name or v.Name == name) then at = i break end
        end
        if at then
            table.remove(list, at)
            UL.localItems[cat][name] = nil
        else
            list[#list + 1] = { name, { 255, 255, 255 } }
            UL.localItems[cat][name] = true
        end
        ad[cat] = list
    elseif STRING_KEYS[cat] then
        if ad[cat] == name then
            ad[cat] = ""
            UL.localItems[cat][name] = nil
        else
            ad[cat] = name
            UL.localItems[cat][name] = true
        end
    else
        return nil
    end
    reload(ap)
    return {}
end

local function hookInventory()
    findAero()
    local svc = Services and Services.InventoryService
    if type(svc) ~= "table" then return false end
    g.__OTHUB_COS_ORIG = g.__OTHUB_COS_ORIG or {}
    local store = g.__OTHUB_COS_ORIG
    store.EquipItem = store.EquipItem or svc.EquipItem
    store.EquipEffect = store.EquipEffect or svc.EquipEffect
    store.InvOwner = svc
    local realItem, realEffect = store.EquipItem, store.EquipEffect
    svc.EquipItem = function(self, cat, name, side, ...)
        if M.alive and UL.on and type(cat) == "string" and type(name) == "string" and not reallyOwned(cat, name) then
            local res = localEquip(cat, name, side)
            if res then return res end
        end
        return realItem(self, cat, name, side, ...)
    end
    svc.EquipEffect = function(self, name, ...)
        if M.alive and UL.on and type(name) == "string" and UL.addedFx[name] then
            greenLocal = name
            return true
        end
        if M.alive and UL.on then greenLocal = nil end
        return realEffect(self, name, ...)
    end
    return true
end

local function setUnlock(on)
    on = on and true or false
    if on == UL.on then return true end
    local pd = profile()
    if not pd or type(pd.Inventory) ~= "table" then return false, "profile not loaded" end
    local inv = pd.Inventory
    if on then
        if not hookInventory() then return false, "locker not available" end
        UL.realGreen = pd.GreenEffect
        for cat, items in pairs(accCfg) do
            if type(items) == "table" and cat ~= "Stores" and cat ~= "SkinTone" then
                local first = next(items)
                if type(first) == "string" and type(items[first]) == "table" then
                    if type(inv[cat]) ~= "table" then inv[cat] = {} UL.createdCat[cat] = true end
                    UL.added[cat] = UL.added[cat] or {}
                    for name in pairs(items) do
                        if inv[cat][name] == nil then
                            inv[cat][name] = { 255, 255, 255 }
                            UL.added[cat][name] = true
                        end
                    end
                end
            end
        end
        if type(inv.GreenEffects) == "table" and type(fxCfg.Effects) == "table" then
            for name in pairs(fxCfg.Effects) do
                if not table.find(inv.GreenEffects, name) then
                    table.insert(inv.GreenEffects, name)
                    UL.addedFx[name] = true
                end
            end
        end
        UL.on = true
    else
        UL.on = false
        for cat, names in pairs(UL.added) do
            if UL.createdCat[cat] then inv[cat] = nil
            elseif type(inv[cat]) == "table" then
                for name in pairs(names) do inv[cat][name] = nil end
            end
        end
        if type(inv.GreenEffects) == "table" then
            for i = #inv.GreenEffects, 1, -1 do
                if UL.addedFx[inv.GreenEffects[i]] then table.remove(inv.GreenEffects, i) end
            end
        end
        if greenLocal then pd.GreenEffect = UL.realGreen end
        greenLocal = nil
        -- take off anything that was only equipped locally
        local ap = appearance()
        if ap then
            local ad, dirty = ap.appearanceData, false
            for cat, names in pairs(UL.localItems) do
                if next(names) then
                    dirty = true
                    restoreKey(ad, cat)
                end
            end
            if dirty then
                if M.enabled then applyAllPending(ap) end
                reload(ap)
            end
        end
        UL.added, UL.createdCat, UL.addedFx, UL.localItems = {}, {}, {}, {}
    end
    return true
end

-- ------------------------------------------------------------------ name changer
local NC = { on = false, name = "" }
M.nameChanger = NC
local weak = { __mode = "k" }
local ncOrig, ncApplied, ncHooked = setmetatable({}, weak), setmetatable({}, weak), setmetatable({}, weak)
local ncConns = {}

local function realNames()
    local list = { LP.Name }
    local dn = LP.DisplayName
    if type(dn) == "string" and dn ~= "" and dn ~= LP.Name then list[#list + 1] = dn end
    return list
end

local function swap(text)
    local changed = false
    for _, real in ipairs(realNames()) do
        local s = text:find(real, 1, true)
        if s then
            local fake = NC.name:gsub("%%", "%%%%")
            text = text:gsub(real:gsub("%p", "%%%0"), fake)
            changed = true
        end
    end
    return text, changed
end

local function touch(lbl)
    if not NC.on or NC.name == "" then return end
    local ok, txt = pcall(function() return lbl.Text end)
    if not ok or type(txt) ~= "string" or txt == "" then return end
    if ncApplied[lbl] == txt then return end
    local new, changed = swap(txt)
    if not changed then return end
    ncOrig[lbl], ncApplied[lbl] = txt, new
    pcall(function() lbl.Text = new end)
    if not ncHooked[lbl] then
        local okc, conn = pcall(function()
            return lbl:GetPropertyChangedSignal("Text"):Connect(function() touch(lbl) end)
        end)
        if okc then ncHooked[lbl] = conn end
    end
end

local function isText(d) return d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") end

local function ncRoots()
    local roots = {}
    local pg = LP:FindFirstChildOfClass("PlayerGui")
    if pg then roots[#roots + 1] = pg end
    pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)
    pcall(function() if gethui then local h = gethui() if h then roots[#roots + 1] = h end end end)
    local ap = appearance()
    if ap and typeof(ap.model) == "Instance" then roots[#roots + 1] = ap.model end
    return roots
end

local function ncScan()
    for _, root in ipairs(ncRoots()) do
        pcall(function()
            for _, d in ipairs(root:GetDescendants()) do
                if isText(d) then touch(d) end
            end
        end)
    end
end

local function ncRestore()
    for lbl, orig in pairs(ncOrig) do
        pcall(function()
            if lbl.Parent and lbl.Text == ncApplied[lbl] then lbl.Text = orig end
        end)
    end
    for lbl, conn in pairs(ncHooked) do pcall(function() conn:Disconnect() end) ncHooked[lbl] = nil end
    for k in pairs(ncOrig) do ncOrig[k] = nil end
    for k in pairs(ncApplied) do ncApplied[k] = nil end
end

local function ncListen()
    for _, c in ipairs(ncConns) do pcall(function() c:Disconnect() end) end
    ncConns = {}
    for _, root in ipairs(ncRoots()) do
        pcall(function()
            ncConns[#ncConns + 1] = root.DescendantAdded:Connect(function(d)
                if NC.on and isText(d) then task.defer(touch, d) end
            end)
        end)
    end
end

function NC.setEnabled(on)
    on = on and true or false
    NC.on = on
    ncRestore()
    if on then
        ncListen()
        ncScan()
    else
        for _, c in ipairs(ncConns) do pcall(function() c:Disconnect() end) end
        ncConns = {}
    end
    return true
end

function NC.setName(txt)
    NC.name = tostring(txt or "")
    if NC.on then
        ncRestore()
        ncScan()
    end
    return true
end

-- ------------------------------------------------------------------ dispatcher
local OWN = { oh_cos_on = true, oh_unlock_cosmetics = true, oh_cos_greenfx = true,
    oh_cos_logo = true, oh_cos_logo_color = true, oh_name_changer = true, oh_fake_name = true }

function M.owns(flag) return OWN[flag] == true or M.MAP[flag] ~= nil end

function M.set(flag, value)
    if flag == "oh_cos_on" then return M.setEnabled(value == true)
    elseif flag == "oh_unlock_cosmetics" then
        UL.want = (value == true)
        setUnlock(UL.want)          -- if the profile isn't loaded yet the watcher retries
        return true
    elseif flag == "oh_cos_greenfx" then M.pending[flag] = value return true
    elseif flag == "oh_cos_logo" or flag == "oh_cos_logo_color" then
        M.pending[flag] = value
        return applyLogo()
    elseif flag == "oh_name_changer" then return NC.setEnabled(value == true)
    elseif flag == "oh_fake_name" then return NC.setName(value)
    elseif M.MAP[flag] then return applyPicker(flag, value) end
    return false, "not a cosmetics flag"
end
M.apply = M.set

-- respawns: this game swaps the rig under workspace.Characters without firing
-- CharacterAdded, so watch the model instead.
local lastModel
task.spawn(function()
    while M.alive do
        task.wait(1.5)
        pcall(hookGreen)
        if UL.want ~= nil and UL.want ~= UL.on then pcall(setUnlock, UL.want) end
        local ap = appearance()
        local model = ap and ap.model
        if model and model ~= lastModel then
            lastModel = model
            baseline, baselineModel = nil, nil
            local need = false
            for flag, v in pairs(M.pending) do
                if M.MAP[flag] and not isNone(v) then need = true break end
            end
            if M.enabled and need then
                task.wait(1)
                local ap2 = appearance()
                if ap2 then
                    snapshot(ap2)
                    applyAllPending(ap2)
                    reload(ap2)
                end
            end
            pcall(applyLogo)
            if NC.on then ncListen() ncScan() end
        elseif NC.on then
            ncScan()                         -- cheap safety net for late text
        end
    end
end)

function M.destroy()
    pcall(NC.setEnabled, false)
    pcall(setUnlock, false)
    pcall(M.setEnabled, false)
    clearLogo()
    M.alive = false
    local store = g.__OTHUB_COS_ORIG
    if type(store) == "table" then
        pcall(function() if store.RunEffectOwner and store.RunEffect then store.RunEffectOwner.RunEffect = store.RunEffect end end)
        pcall(function()
            if store.InvOwner then
                if store.EquipItem then store.InvOwner.EquipItem = store.EquipItem end
                if store.EquipEffect then store.InvOwner.EquipEffect = store.EquipEffect end
            end
        end)
    end
    g.__OTHUB_COS_ORIG = nil
end

pcall(hookGreen)
return M

end)()
