do
    local reg = OTHUB_SHELL.controlRegistry
    local function findCtl(flag)
        for i = 1, #reg do if reg[i] and reg[i].name == flag then return reg[i] end end
    end
    local function setFlag(flag, v)
        local c = findCtl(flag)
        if c and c.setValue then
            local ok, err = pcall(c.setValue, v)
            if not ok then return false, err end
            return true
        end
        return false, "no control"
    end
    local U

    -- Combo presets: the preset names survive in the menu but their move lists
    -- were in the module that never shipped, so these sequences are rebuilt.
    local COMBO_PRESETS = {
        ["Ankle Breaker"]      = { "Crossover", "Double Crossover", "Behind the Back", "Snatchback" },
        ["Size-Up Blowby"]     = { "Hesi", "Tween", "Double Tween", "Crossover" },
        ["Shifty Iso"]         = { "Tween", "Behind the Back", "Hesi", "Crossover", "Spin" },
        ["Snatch Pullup"]      = { "Hesi", "Crossover", "Snatchback" },
        ["Spin Counter"]       = { "Crossover", "Spin", "Half Spin" },
        ["Shammgod Freeze"]    = { "Hesi", "Shammgod", "Crossover" },
        ["Double Tween Shake"] = { "Double Tween", "Hesi", "Double Crossover" },
    }
    local function loadComboPreset(name)
        local seq = COMBO_PRESETS[name]
        if not seq then return true end
        for i = 1, 6 do
            local flag, move = "Combo1_Move" .. i, seq[i] or "None"
            pcall(function()
                local wc = U and U.window and U.window._controls and U.window._controls[flag]
                if wc and wc.Set then wc.Set(move) end
            end)
            setFlag(flag, move)
        end
        return true
    end

    local function onValue(T, v)
        if not T or not T.flag then return true end
        -- keybind controls only accept a key *name*
        if typeof(v) == "EnumItem" then v = v.Name end
        -- rebuilt modules
        if OTHUB_COSMETICS.owns(T.flag) then return OTHUB_COSMETICS.set(T.flag, v) end
        if T.flag == "oh_combo_preset" then return loadComboPreset(v) end
        -- V10/V11/V12 need the aim-correction engine (_otV10Core), which lives in
        -- the VM-protected bytecode and was never in the capture. Calling it threw
        -- inside a pcall, so picking one silently did nothing. Fall back loudly.
        if T.flag == "pg_autotime_eq" and (v == "V10" or v == "V11" or v == "V12") then
            local fallback = "V9"
            setFlag(T.flag, fallback)
            pcall(function()
                local wc = U and U.window and U.window._controls and U.window._controls[T.flag]
                if wc and wc.Set then wc.Set(fallback) end
            end)
            return false, v .. " needs the protected aim engine - using " .. fallback
        end
        if T.fanout then
            local sel = {}
            if type(v) == "table" then
                for k2, v2 in pairs(v) do
                    if type(k2) == "number" then sel[v2] = true elseif v2 then sel[k2] = true end
                end
            elseif type(v) == "string" then
                for part in v:gmatch("[^,]+") do sel[part] = true end
            end
            for opt, f in pairs(T.fanout) do setFlag(f, sel[opt] == true) end
        end
        local ok, err = setFlag(T.flag, v)
        if not ok and err ~= "no control" then return false, err end
        return true
    end

    local gameKey = OTHUB_GAMES.detect(game) or "practical"
    local gameName = OTHUB_GAMES.name(gameKey)
    if gameName == "Unknown" then gameName = "Practical Basketball" end
    local catalog = OTHUB_CATALOG.new()
    catalog:addMany(OTHUB_FEATURES)
    local model = catalog:resolve({caps = {}, roles = {}}, gameKey)
    model.menusets = (#model.menusets > 0) and model.menusets or {"Main"}

    -- The cosmetics pickers ship as options={"None"}; the real lists were filled
    -- in by the module that never shipped. Populate them from the game catalogue.
    pcall(function()
        for _, sn in ipairs(model.menusets) do
            local set = model.sets[sn]
            for _, tn in ipairs(set.tabOrder) do
                local tab = set.tabs[tn]
                for _, s in ipairs(tab.secOrder) do
                    for _, c in ipairs(tab.secs[s].controls) do
                        local opts = c.flag and OTHUB_COSMETICS.options(c.flag)
                        if opts then
                            if #opts > 1 then
                                c.options = opts
