                            end
                        end
                    end
                end
            end
        end
    end)

    U = {
        gameName = gameName, gameKey = gameKey, summary = "Owner build", hideLocked = true, real = true,
        caps = {}, current = model.menusets[1], loaded = {}, model = model,
        onSwitch = function(m) U.current = m end,
        onValue = onValue,
        -- Toggles go through onToggle (not onValue). Without it every toggle click
        -- failed silently and only took effect from the saved config on the next join.
        onToggle = function(T, state) return onValue(T, state == true) end,
        start = function(stage) U.loaded[stage] = true; return true end,
        warn = function(m) _log(tostring(m)) end,
        notifyBuy = function() end,
    }
    local okB, errB = pcall(OTHUB_HUB.build, model, U)
    if not okB then _log("hub build error: " .. tostring(errB)) end
    pcall(function() getgenv().OTHUB_SESSION = U end)

    task.defer(function()
        local win = U.window
        if not win then return end
        for _, setName in ipairs(model.menusets) do
            local set = model.sets[setName]
            for _, tn in ipairs(set.tabOrder) do
                local tab = set.tabs[tn]
                for _, sn in ipairs(tab.secOrder) do
                    for _, c in ipairs(tab.secs[sn].controls) do
                        if c.flag and c.type ~= "button" and c.type ~= "label" then
                            local v
                            pcall(function() v = win._cfg.get(c.flag) end)
                            if v == nil then v = c.default end
                            if v ~= nil then onValue(c, v) end
                        end
                    end
                end
            end
        end
        _log(("loaded %s | %d controls registered"):format(gameName, #reg))
    end)
